package app.space.notes.domain;
import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;
public class TypingStyleTest {
    @Test public void capturesCommonFormattingNotTextLinksOrNumbers(){RichText rich=new RichText("Secret words",Arrays.asList(new Note.Mark("bold",0,6),new Note.Mark("bold",6,12),new Note.Mark("italic",0,6),new Note.Mark("font",0,12,"serif"),new Note.Mark("link",0,6,"https://example.com"),new Note.Mark("number",0,12,"1")));TypingStyle style=TypingStyle.capture(rich,0,12);assertEquals("bold=;font=serif;",style.encode());assertFalse(style.encode().contains("Secret"));assertFalse(style.encode().contains("example"));}
    @Test public void selectedReplacementPreservesOutsideAndLinks(){RichText rich=new RichText("before after",Arrays.asList(new Note.Mark("bold",0,12),new Note.Mark("link",7,12,"https://example.com")));RichText changed=new TypingStyle(Collections.singletonMap("italic","")).apply(rich,7,12);assertEquals("before after",changed.text);assertTrue(changed.marks.stream().anyMatch(m->m.type.equals("bold") && m.end==7));assertTrue(changed.marks.stream().anyMatch(m->m.type.equals("italic") && m.start==7));assertTrue(changed.marks.stream().anyMatch(m->m.type.equals("link")));assertEquals(2,rich.marks.size());}
    @Test public void normalStyleRemovesEmphasisButNotLinkOrNumber(){RichText rich=new RichText("body",Arrays.asList(new Note.Mark("bold",0,4),new Note.Mark("number",0,4,"1"),new Note.Mark("link",0,4,"https://example.com")));RichText result=TypingStyle.normal().apply(rich,0,4);assertEquals(2,result.marks.size());assertFalse(result.marks.stream().anyMatch(m->m.type.equals("bold")));}
    @Test public void styleEncodingIsCanonicalBoundedAndRejectsUnsupportedActions(){TypingStyle style=TypingStyle.normal().with("size","24").with("font","monospace").with("bold","");assertEquals(style.encode(),TypingStyle.decode(style.encode()).encode());for(String invalid:Arrays.asList("link=https://example.com;","size=73;","size=024;","bold=;bold=;","size=24;font=serif;","h1=;h2=;","unknown=;"))assertThrows(IllegalArgumentException.class,()->TypingStyle.decode(invalid));}
    @Test public void emptyAndCaretCaptureNeverCopiesCharacters(){assertEquals("",TypingStyle.capture(new RichText("",Collections.emptyList()),0,0).encode());RichText rich=new RichText("😀text",Arrays.asList(new Note.Mark("bold",0,2)));assertEquals("bold=;",TypingStyle.capture(rich,2,2).encode());assertThrows(IllegalArgumentException.class,()->TypingStyle.normal().apply(rich,1,2));}
    @Test public void applyingHeadingPresetTwiceDoesNotToggleItOff(){TypingStyle style=TypingStyle.normal().with("h1","");RichText one=style.apply(new RichText("title\nbody",Collections.emptyList()),0,5);RichText two=style.apply(one,0,5);assertTrue(one.same(two));assertFalse(style.withoutHeading().values.containsKey("h1"));}
    @Test public void switchingHeadingKeepsOnlyOneAndFontPersists(){TypingStyle style=TypingStyle.normal().with("h1","").with("font","serif").with("h2","");assertFalse(style.values.containsKey("h1"));assertTrue(style.values.containsKey("h2"));assertEquals("serif",style.withoutHeading().values.get("font"));assertThrows(UnsupportedOperationException.class,()->style.values.put("bold",""));}
    @Test public void repeatedTypingCoalescesAdjacentMarksInsteadOfExhaustingMarkLimit(){TypingStyle style=TypingStyle.normal().with("bold","").with("font","serif").with("size","24");RichText rich=new RichText("",Collections.emptyList());for(int i=0;i<1200;i++){rich=style.apply(new RichText(rich.text+"a",rich.marks),i,i+1);}assertEquals(3,rich.marks.size());assertTrue(rich.marks.stream().allMatch(mark->mark.start==0 && mark.end==1200));}

}
